using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Integration.Aspire;

namespace MyApp.Evals;

[TestClass]
public class EvalTests : EvalTestBase
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = ConfigureReporting(context);
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    protected override ReportingConfiguration? ReportingConfiguration => s_reportingConfiguration;

    private static ReportingConfiguration ConfigureReporting(TestContext context)
    {
        var storageDir = Path.Combine(context.TestRunResultsDirectory!, "eval-results");

        return DiskBasedReportingConfiguration.Create(
            storageRootDir: storageDir,
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new GroundednessEvaluator(),
                new FluencyEvaluator(),
            ]);
    }

    protected override async Task<IChatClient> GetChatClientAsync()
    {
        var appHost = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        var app = await appHost.BuildAsync();
        await app.StartAsync();

        return app.CreateChatClient("chat");
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndRelevant()
    {
        await using var scenario = await CreateScenarioRunAsync();
        var chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Say hello and introduce yourself briefly."),
        };

        var response = await chatClient.GetResponseAsync(messages);

        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task AnswerQuestion_IsGroundedAndFluent()
    {
        await using var scenario = await CreateScenarioRunAsync();
        var chatClient = scenario.ChatClient!;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that answers questions about .NET."),
            new(ChatRole.User, "What is dependency injection in .NET?"),
        };

        var response = await chatClient.GetResponseAsync(messages);

        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }
}

